/* Example: Color-code node types */
.canvas-node-container[data-type="text"] {
  border: 2px solid #4A90E2; /* Blue for text cards */
}

.canvas-node-container[data-type="file"] {
  border: 2px solid #50E3C2; /* Green for file nodes */
}

/* Group background opacity */
.canvas-node-container[data-is-group="true"] {
  opacity: 0.3;
}

/* Edge styling */
.canvas-edge {
  stroke: #B8A6DB; /* Purple connections */
  stroke-width: 2px;
}

